begin transaction isolation level repeatable read read only;set local statement_timeout='15s';
select jsonb_build_object('observedAt',clock_timestamp(),
'ledger',(select jsonb_build_object('count',count(*),'head',max(version)) from supabase_migrations.schema_migrations),
'legacyShape',jsonb_build_object('budgetsMissingPayer',(select count(*) from public.budget_items where payer_id is null),'actualsMissingPayer',(select count(*) from public.actual_expenses where payer_id is null),'budgetsWithoutExplicitParticipants',(select count(*) from public.budget_items b where not exists(select 1 from public.budget_item_participants p where p.budget_item_id=b.id)),'actualsWithoutExplicitParticipants',(select count(*) from public.actual_expenses a where not exists(select 1 from public.actual_expense_participants p where p.actual_expense_id=a.id)),'nonApprovedBudgetParticipants',(select count(*) from public.budget_item_participants p join public.budget_items b on b.id=p.budget_item_id where not exists(select 1 from public.trip_members m where m.trip_id=b.trip_id and m.user_id=p.user_id and m.status='approved')),'nonApprovedActualParticipants',(select count(*) from public.actual_expense_participants p join public.actual_expenses a on a.id=p.actual_expense_id where not exists(select 1 from public.trip_members m where m.trip_id=a.trip_id and m.user_id=p.user_id and m.status='approved')),'tripsWithoutInitializedRates',(select count(*) from public.trips where not coalesce(budget_exchange_rates?'rates',false)),'legacyNonIntegerActualTwd',(select count(*) from public.actual_expenses where twd_amount<>round(twd_amount)),'actualsMissingPaidAt',(select count(*) from public.actual_expenses where paid_at is null),'customBudgetSharesMismatch',(select count(*) from public.budget_items b where b.pricing_mode='custom' and b.amount is distinct from (select sum(share_amount) from public.budget_item_participants p where p.budget_item_id=b.id))),
'activeLeases',(select count(*) from app_private.budget_edit_leases where expires_at>clock_timestamp())) review;
commit;
